test("exact anchor points", () => {
  expect(portableSin(0)).toBe(0);
  expect(portableSin(Math.PI / 2)).toBeCloseTo(1, 9);
  expect(portableSin(-Math.PI / 2)).toBeCloseTo(-1, 9);
  expect(portableCos(0)).toBeCloseTo(1, 12);
});

